public Guid Id { get; private set; }
    public Guid GroupId { get; private set; }
    public string Name { get; private set; } = null!;
    public string? Description { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }
    public DateTime? DeletedAt { get; private set; }

public static ResourceType Create(CreateResourceTypeCommand command, DateTime now)
        => new()
        {
            Id = Guid.CreateVersion7(),
            GroupId = command.GroupId,
            Name = command.Name,
            Description = command.Description,
            CreatedAt = now,
            UpdatedAt = now
        };

public void Update(UpdateResourceTypeCommand command, DateTime now)
    {
        Name = command.Name;
        Description = command.Description;
        UpdatedAt = now;
    }

public void Delete(DateTime now)
    {
        DeletedAt = now;
        UpdatedAt = now;
    }

var group = await _dataProvider.GetGroupAsync(command.GroupId, cancellationToken);

        if (group is null)
            throw new ResourcesDomainException("Group not found.");

        if (string.IsNullOrWhiteSpace(command.Name))
            throw new ResourcesDomainException("Resource type name cannot be empty.");

        if (group.OwnerId != command.CallerId)
            throw new ResourcesForbiddenException("Only the group owner may create a resource type.");

var normalizedName = command.Name.Trim();
        var nameExists = await _dataProvider.ExistsByGroupAndNameAsync(command.GroupId, normalizedName, excludeId: null, cancellationToken);

        if (nameExists)
            throw new ResourceTypeNameAlreadyExistsException(command.GroupId, normalizedName);

var resourceType = await _dataProvider.GetResourceTypeWithDefinitionsAsync(command.TypeId, cancellationToken);

        if (resourceType is null)
            throw new ResourcesDomainException("Resource type not found.");

        var group = await _dataProvider.GetGroupAsync(resourceType.GroupId, cancellationToken);

        if (group is null || group.OwnerId != command.RequesterId)
            throw new ResourcesForbiddenException("Only the group owner may update a resource type.");

builder.ToTable("resource_types");
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Name).HasMaxLength(200).IsRequired();
        builder.Property(x => x.Description).HasMaxLength(2000);
        builder.HasQueryFilter(x => x.DeletedAt == null);

        builder.HasIndex(t => new { t.GroupId, t.Name }).IsUnique();

        builder.HasMany(x => x.PropertyDefinitions)
            .WithOne()
            .HasForeignKey(x => x.ResourceTypeId)
            .OnDelete(DeleteBehavior.Cascade);
